k='z';E=lambda a,b=None:ev(k,a,b);F=lambda s,a,b,kind='inference':finding(k,s,a,b,kind)
units=[unit(k,244,'羽毛指挥弓手覆盖破隐；萧御突进斩首，队友借其拉散阵型攻击。','独行突击为团队创造机会，逃脱并非无伤。',12673,12718),unit(k,245,'主箭塔攻下获荣耀；萧御把个人所获弓也列入团队分配，选择换荣耀。比蒙出现。','城门压力减轻但箭塔可在半小时后重启；个人脱队继续赌局。',12742,12787),unit(k,246,'萧御侦查比蒙和驯兽师，风野组织万人战阵并计划将驯兽师单独喂给萧御。','个人无法战胜的敌人被公会组织资源重新定义。',12792,12843),unit(k,247,'公会顶住比蒙狂暴，付出上千死亡最终击杀；公会成员避让萧御，糖果受到抢目标干扰。','赌约环境不对称；组织胜利依赖实际人员损失。',12856,12908),unit(k,248,'风野要求戴斗篷并展示实力以平息分配异议；萧御把无攻击力驯兽师连控作输出演示。','特殊待遇需要向公会成员证明价值；满能量爆破突破。',12917,12975),unit(k,249,'驯兽师击杀使萧御升26级获2000荣耀、百夫长和生命之戒；噬魂戒再吸魂。','收益兑现但无干扰输出不能等同正常PK，噬魂戒效果仍未知。',12980,13032,['噬魂戒已吞两个强魂，解封效果未知。']),unit(k,250,'糖果取消稳胜赌局并约任务后公平决斗；第一环完成，装备兑换、经验结算后到28级。','赌约作废不是萧御获胜；接触导师恩斯。',13041,13109),unit(k,251,'领取300功勋与龙翔术，明确脚踢依赖；接受第二环刺杀思科。','奖励把护腿旧属性转成新体系，NPC另有考验目的仍属萧御推测。',13134,13174),unit(k,252,'十贼俯瞰尚在谈判的主战场，再突袭护送矿工的26人队，先杀探隐与治疗。','规模奇观后回到小队分工，龙翔初用仅67%仍打断治疗。',13180,13244)]
d={'worldbuilding':[F('荣耀决定军衔和军装，功勋决定爵位与NPC任务待遇，两者不可混为一种积分。',13138,13148,'fact')],'characters':[F('糖果不愿占中途离场的便宜而主动取消稳胜赌局，使萧御对其有局部改观，尚不等于团队责任问题已解决。',13041,13059)],'plot':[F('个人箭塔突破、公会组织消耗、单人演示及国家任务奖励构成多级结算；各条线在资源分配处交汇。',12742,12779)],'style':[F('大型战场以海洋、蝗虫、坦克等体量比喻放大规模，再用血量与队形让战斗可操作；也有大量赞叹性旁观视角。',12856,12908)],'narrative':[F('先让众人质疑独占驯兽师资源，再以公开输出转为公会自豪，读者知道其商业投资背景而普通成员猜测秘密高手。',12917,12933)],'dialogue':[F('取消赌局的短讯把胜负从计数改成公平条件；对手坚持而主动让利，产生超出嘲讽台词的角色信息。',13051,13059)],'pacing':[F('比蒙万人消耗与驯兽师十五秒输出在时间尺度上对照，领奖后立即发布第二环，阶段收束同时开新期待。',12959,12976)],'themes':[F('风野的赠与由黑赛共同收益支撑，个人收益依赖公会成员的死亡与服从，组织资源和个人英雄形成张力。',12879,12885)],'continuity':[F('第一环已完成，十环尚远；赌局解除，决斗只是约定；龙翔需脚踢和自身双冷却。正文多次天使/邪恶阵营误称与弓手写成盗贼应单列。',13051,13071)]}
